#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define rep(i, n) for(int i = 0; i < (n); i += 1)
#define len(a) ((int)(a).size())

const ll inf = 1e18;
mt19937 rnd(234);

int n;
ll k;
vector<ll> a, b;

inline void solve() {
    cin >> n >> k;
    a.resize(n);
    rep(i, n) {
        cin >> a[i];
    }
    b.resize(n);
    rep(i, n) {
        cin >> b[i];
    }
    rep(i, n) {
        if (a[i] > b[i]) swap(a[i], b[i]);
    }
    ll base_cost = 0;
    rep(i, n) {
        base_cost += a[i] * b[i];
    }
    vector <int> srtd(n);
    rep(i, n) {
        srtd[i] = i;
    }
    sort(all(srtd), [&](int i, int j) {
        return b[i] > b[j];
        });
    vector<int> pos(n);
    rep(i, n) {
        pos[srtd[i]] = i;
    }
    vector<ll> psums(n + 1);
    vector<ll> psums_cost(n + 1);
    rep(i, n) {
        psums[i + 1] = psums[i] + a[srtd[i]];
        psums_cost[i + 1] = psums_cost[i] + a[srtd[i]] * b[srtd[i]];
    }
    auto get = [&](ll x, int bnd) {
        ll res = 0;
        if (psums[pos[bnd]] < x) {
            x += a[bnd];
            res -= a[bnd] * b[bnd];
        }
        if (x >= psums.back()) {
            res += psums_cost.back();
            return res;
        }
        int flex = upper_bound(all(psums), x) - psums.begin() - 1;
        res += psums_cost[flex];
        ll rest = x - psums[flex];
        if (rest > 0) {
            res += b[srtd[flex]] * rest;
        }
        return res;
        };
    ll res = base_cost;
    rep(i, n) {
        auto get_bob = [&](ll to_move) {
            ll res = base_cost - a[i] * b[i] + (a[i] - to_move) * (b[i] + to_move);
            res -= get(k - to_move, i);
            ll new_moves = min(k - to_move, psums.back() - a[i]);
            res += new_moves * (a[i] - to_move);
            return res;
            };
        ll tl = 0;
        ll tr = min(k, a[i]);
        while (tl + 10 < tr) {
            ll tm1 = (2 * tl + tr) / 3;
            ll tm2 = (tl + 2 * tr) / 3;
            if (get_bob(tm1) < get_bob(tm2)) {
                tr = tm2;;
            }
            else {
                tl = tm1;
            }
        }
        for (ll j = tl; j <= tr; j += 1) {
            res = min(res, get_bob(j));
        }
    }
    cout << res << "\n";
}

int32_t main() {
    if (1) {
        ios::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);
    }
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
